add_action( 'customize_register', 'perfectpixel_customizer_coupon_setting' );
add_action( 'wp', 'perfectpixel_customizer_coupon_apply' );

function perfectpixel_customizer_coupon_setting( $wp_customize ) {
	$wp_customize->add_setting(
		'perfectpixel_hide_checkout_coupon',
		array(
			'type'              => 'option',
			'default'           => 'no',
			'capability'        => 'manage_woocommerce',
			'sanitize_callback' => function ( $value ) {
				return 'yes' === $value || true === $value || '1' === (string) $value ? 'yes' : 'no';
			},
		)
	);
	$wp_customize->add_control(
		'perfectpixel_hide_checkout_coupon',
		array(
			'label'    => '{{customizer_label}}',
			'section'  => 'woocommerce_checkout',
			'settings' => 'perfectpixel_hide_checkout_coupon',
			'type'     => 'checkbox',
		)
	);
}

function perfectpixel_customizer_coupon_apply() {
	if ( 'yes' === get_option( 'perfectpixel_hide_checkout_coupon', 'no' ) ) {
		remove_action( 'woocommerce_before_checkout_form', 'woocommerce_checkout_coupon_form', 10 );
	}
}
